#!/usr/bin/env node
/**
 * Parse the root CHANGELOG.md (auto-generated by `changeset version`) into a
 * JSON manifest the /changelog/ Astro page renders. Replaces the old
 * "list pending changesets" behavior — this shows the actual published
 * version history instead.
 *
 * CHANGELOG.md shape (changesets/changelog-github):
 *
 *   # @schmooky/zvuk
 *
 *   ## 0.1.0
 *
 *   ### Minor Changes
 *
 *   - [`<sha>`](github commit url) Thanks [@user](url)! - <body>
 *
 *   ### Patch Changes
 *
 *   - ...
 *
 *   ## 0.0.5
 *   ...
 *
 * Each version becomes one entry; entries within a version are bucketed by
 * bump (Major / Minor / Patch). When the file is missing (fresh clone with
 * no published versions yet) we write an empty array — the page handles it.
 */
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(__dirname, '..');
const CHANGELOG = resolve(ROOT, '../CHANGELOG.md');
const OUT = resolve(ROOT, 'src/content/changelog.json');

async function main() {
  await mkdir(dirname(OUT), { recursive: true });
  let entries = [];
  try {
    const raw = await readFile(CHANGELOG, 'utf-8');
    entries = parse(raw);
  } catch (e) {
    console.warn('[build-changelog] CHANGELOG.md not loadable:', e?.message ?? e);
  }
  await writeFile(OUT, `${JSON.stringify(entries, null, 2)}\n`, 'utf-8');
  console.log(`[build-changelog] Wrote ${entries.length} version(s) to ${OUT}`);
}

function parse(raw) {
  const lines = raw.split(/\r?\n/);
  const versions = [];
  let current = null;
  let bucket = null; // 'major' | 'minor' | 'patch' — the section we're adding into

  for (const line of lines) {
    // ## 0.1.0 — start a new version
    const versionMatch = /^##\s+(\S+)\s*$/.exec(line);
    if (versionMatch) {
      if (current) versions.push(current);
      current = { version: versionMatch[1], major: [], minor: [], patch: [] };
      bucket = null;
      continue;
    }
    if (!current) continue;

    // ### Minor Changes — switch the active bucket
    const sectionMatch = /^###\s+(Major|Minor|Patch)\s+Changes\s*$/i.exec(line);
    if (sectionMatch) {
      bucket = sectionMatch[1].toLowerCase();
      continue;
    }

    // - [`abc`](url) Thanks [@user](url)! - body...
    const itemMatch = /^-\s+(.+)$/.exec(line);
    if (itemMatch && bucket && current[bucket]) {
      current[bucket].push({ raw: itemMatch[1], body: '' });
      continue;
    }

    // Continuation line of the previous bullet (indented).
    if (bucket && current[bucket].length > 0 && /^\s+\S/.test(line)) {
      const last = current[bucket][current[bucket].length - 1];
      last.raw += `\n${line.replace(/^\s{2}/, '')}`;
    }
  }
  if (current) versions.push(current);

  return versions.map((v) => ({
    version: v.version,
    major: v.major.map(formatItem),
    minor: v.minor.map(formatItem),
    patch: v.patch.map(formatItem),
  }));
}

/**
 * Split a raw bullet into `{ commitSha?, commitUrl?, author?, body }`. The
 * standard changesets/changelog-github format is:
 *
 *   [`<sha>`](commit-url) Thanks [@user](profile-url)! - <body>
 */
function formatItem(item) {
  const result = { body: item.raw };
  const m = /^\[`([^`]+)`\]\((https?:[^)]+)\)\s+Thanks\s+\[@([^\]]+)\]\(https?:[^)]+\)!\s*-\s*([\s\S]+)$/.exec(item.raw);
  if (m) {
    result.commitSha = m[1];
    result.commitUrl = m[2];
    result.author = m[3];
    result.body = m[4].trim();
  }
  return result;
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
